import re
from decimal import Decimal

from django.db import migrations, models

# "Stock actual: 14.00" -> "Stock actual: 14" en las alertas ya guardadas.
DECIMALES_EN_CERO = re.compile(r"(?<![\d.,])(-?\d+)\.00(?!\d)")


def limpiar_mensajes_de_alertas(apps, schema_editor):
    Alerta = apps.get_model("nexofaena", "Alerta")
    for alerta in Alerta.objects.filter(mensaje__contains=".00").only("id", "mensaje").iterator():
        limpio = DECIMALES_EN_CERO.sub(lambda m: m.group(1), alerta.mensaje)
        if limpio != alerta.mensaje:
            Alerta.objects.filter(pk=alerta.pk).update(mensaje=limpio)


